const event=(name,detail={})=>{window.dispatchEvent(new CustomEvent('nexora:analytics',{detail:{event:name,...detail}}));if(window.dataLayer)window.dataLayer.push({event:name,...detail})};
const btn=(label,href,cls='')=>`<a class="btn ${cls}" href="${/^\/jobs(?:\/|\?|$)/.test(href)?JOBS_URL:href}" data-event="cta_${label.toLowerCase().replace(/[^a-z0-9]+/g,'_')}">${label}<span aria-hidden="true">↗</span></a>`;
