const footer=()=>`<section class="final"><div class="wrap"><span class="tag" style="color:#e6d9fa">YOUR NEXT CHAPTER</span><h2>Your Place in the Beauty Economy Starts Here.</h2><p>Discover a service. Build a business. Find an opportunity. There’s a place for you in Nexora.</p><div class="actions">${btn('Find Beauty Services','https://glow-slot-virid.vercel.app/','light')}${btn('List My Business',SIGNUP_URL,'outline')}${btn('Create My Free Website','/templates/','outline')}${btn('Find Jobs','/jobs/','outline')}${btn('Become a Growth Partner','/growth-partner/','outline')}</div></div></section><footer class="footer"><div class="wrap"><div class="footergrid"><div><a class="logo" href="/"><span class="mark">N</span>NEXORA</a><p>The Global Beauty Growth Network.</p><p>Local businesses. Real professionals.<br>One connected future.</p></div><div><h4>Explore Nexora</h4>${modules.slice(0,6).map(m=>`<a href="/${m[0]}/">${m[2]}</a>`).join('')}</div><div><h4>Grow Together</h4><a href="/growth-partner/">Growth Partner</a><a href="/contact/">Enterprise</a><a href="/about/">About Nexora</a><a href="/contact/">Contact</a><a href="/app/">Nexora App</a><a href="${BASE}/partner/dashboard">Partner Dashboard</a></div><div><h4>Policies & Trust</h4>${legalNames.map(n=>`<a href="/policies/?section=${slug(n)}">${n}</a>`).join('')}</div></div><div class="legal"><p>Nexora provides technology, marketplace, onboarding and discovery services for eligible users and businesses. Features, rewards, payouts and availability may vary by location, category and program terms. Earnings and rewards are not guaranteed.</p><span>© ${new Date().getFullYear()} Nexora</span></div></div></footer><button class="chat" data-contact data-event="cta_contact">◉ &nbsp; Let’s talk</button><nav class="mobilebar" aria-label="Quick navigation"><a href="/discover/"><b>◎</b>Discover</a><a href="/templates/"><b>▧</b>Build</a><a href="/jobs/"><b>↗</b>Jobs</a><a href="/growth-partner/"><b>⤴</b>Partner</a><a href="${LOGIN_URL}"><b>◉</b>Login</a></nav>`;
const ecosystem=()=>`<section class="section" id="ecosystem"><div class="wrap"><div class="head"><div><div class="eyebrow">CONNECTED BY DESIGN</div><h2>One Network.<br>Every Beauty Business.</h2></div><p>From your next haircut to your next business chapter. Meet the ecosystem connecting the entire beauty economy.</p></div><div class="grid">${modules.map((m,i)=>`<article class="card ${i===6?'feature':''}"><div><span class="icon">${m[1]}</span><h3>${m[2]}</h3><span class="tag">${m[3]}</span><p>${m[4]}</p></div><a class="link" href="/${m[0]}/" data-event="ecosystem_${m[0]}">${m[5]} ↗</a></article>`).join('')}</div></div></section>`;
const audienceMarkup=(i=0)=>{const p=people[i];return `<div class="split"><div><span class="mini-tag">FOR ${p[0].toUpperCase()}</span><h2>${p[1]}</h2>${checks(p[2])}${btn(p[3],'/'+p[4]+'/')}</div><img src="/${p[5]}" class="rounded" loading="lazy" alt="${p[0]} in the beauty industry"></div>`};
const audiences=()=>`<section class="section white"><div class="wrap"><div class="eyebrow">YOUR WORLD, CONNECTED</div><h2>Nexora For Everyone.</h2><div class="tabs" role="tablist" aria-label="Your role">${people.map((p,i)=>`<button class="tab" role="tab" id="tab-${i}" aria-controls="audience" aria-selected="${i===0}" data-tab="${i}" tabindex="${i===0?0:-1}">${p[0]}</button>`).join('')}</div><div id="audience" role="tabpanel" aria-labelledby="tab-0">${audienceMarkup()}</div></div></section>`;
